INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7101,1,'psiquiatria','Acolhimento inicial em risco psíquico','Risco','Padronizar acolhimento, estratificação e encaminhamento de pacientes com sofrimento psíquico agudo.','- Confirmar queixa principal e fator precipitante\n- Avaliar ideação suicida, plano e meios\n- Revisar suporte familiar e rede de proteção\n- Definir necessidade de observação/encaminhamento','Priorizar se risco suicida moderado/alto, agitação importante, psicose desorganizada ou ausência de suporte.','Registrar plano de segurança, orientar sinais de alerta e documentar responsável quando aplicável.','risco, urgência, psiquiatria',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7102,1,'pediatria','Febre sem sinais de toxemia','Retorno','Organizar avaliação e orientação domiciliar nos quadros febris de baixa complexidade.','- Confirmar duração da febre\n- Checar hidratação, aceitação alimentar e diurese\n- Revisar vacinação\n- Informar sinais de alarme','Reavaliar rapidamente se prostração, desconforto respiratório, sonolência excessiva ou febre persistente.','Entregar orientação escrita de hidratação, controle térmico e retorno programado.','pediatria, febre, sinais de alarme',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7103,1,'cardiologia','Seguimento ambulatorial de hipertensão','Seguimento','Padronizar consulta de revisão pressórica e adesão ao tratamento.','- Conferir pressão arterial e frequência cardíaca\n- Revisar adesão medicamentosa\n- Checar eventos adversos\n- Solicitar exames conforme risco','Escalonar investigação se PA persistentemente elevada, sintomas de isquemia ou sinais de lesão de órgão-alvo.','Reforçar metas pressóricas, atividade física e retorno com monitorização domiciliar quando possível.','hipertensão, cardiologia, risco cardiovascular',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7104,1,'neurologia','Cefaleia com sinais de atenção','Triagem','Apoiar triagem clínica de cefaleias com necessidade de investigação complementar.','- Caracterizar padrão da dor\n- Revisar déficits focais e alterações visuais\n- Checar uso prévio de analgesia\n- Definir necessidade de neuroimagem','Encaminhar urgência se déficit focal persistente, cefaleia explosiva, febre com rigidez de nuca ou rebaixamento do nível de consciência.','Orientar diário de sintomas, gatilhos e retorno com exames solicitados.','cefaleia, neurologia, red flags',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7105,1,'medico','Check-up clínico e prevenção cardiometabólica','Prevenção','Padronizar atendimento clínico preventivo com foco em fatores de risco, exames de rotina e orientação de estilo de vida.','- Revisar antecedentes pessoais e familiares\n- Avaliar pressão arterial, IMC e circunferência abdominal\n- Solicitar/checar exames laboratoriais periódicos\n- Reforçar plano de prevenção e retorno','Priorizar seguimento se houver hipertensão, obesidade, diabetes, tabagismo ou alterações laboratoriais relevantes.','Orientar alimentação, atividade física, sono, cessação do tabagismo e retorno com exames conforme risco.','clinica medica, prevenção, check-up',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7106,1,'dentista','Avaliação inicial com risco de cárie e periodontal','Triagem','Organizar avaliação odontológica inicial com estratificação de risco, higiene oral e definição do plano terapêutico.','- Identificar queixa principal e dor\n- Avaliar biofilme, sangramento gengival e lesões cariosas\n- Definir necessidade de radiografias\n- Registrar plano imediato e retorno','Antecipar intervenção se dor espontânea, abscesso, sangramento persistente, mobilidade dentária ou suspeita de infecção.','Reforçar técnica de higiene oral, controle de dieta cariogênica e cronograma de tratamento por etapas.','odontologia, cárie, periodontal, triagem',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7107,1,'psicologia','Acolhimento inicial e definição de plano terapêutico','Acolhimento','Padronizar entrevista inicial, mapeamento de demandas, fatores precipitantes e objetivos terapêuticos.','- Identificar demanda principal e contexto atual\n- Levantar história emocional, familiar e ocupacional\n- Avaliar risco psíquico e rede de apoio\n- Definir objetivo inicial e frequência sugerida','Priorizar encaminhamento compartilhado se houver risco de autoagressão, sintomas graves ou prejuízo funcional importante.','Registrar contrato terapêutico, combinados de acompanhamento e indicadores de evolução clínica.','psicologia, acolhimento, plano terapêutico',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7108,1,'ginecologia_obstetricia','Rastreamento ginecológico e seguimento pré-natal habitual','Seguimento','Padronizar consulta preventiva ginecológica e o acompanhamento obstétrico de rotina com foco em sinais de alerta.','- Revisar queixas, ciclo menstrual e histórico obstétrico\n- Conferir exames preventivos e laboratoriais\n- Avaliar sinais de alerta ginecológicos/obstétricos\n- Definir retorno e exames complementares','Escalonar rapidamente se houver sangramento anormal, dor intensa, hipertensão gestacional, redução de movimentos fetais ou sinais infecciosos.','Orientar adesão ao pré-natal, exames periódicos, vacinação e retorno imediato diante de sinais de alerta.','ginecologia, obstetricia, pré-natal, rastreio',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7109,1,'ortopedia_traumatologia','Dor osteomuscular sem trauma grave','Conduta inicial','Padronizar abordagem de dor musculoesquelética ambulatorial com avaliação funcional, analgesia e indicação de imagem.','- Localizar dor e mecanismo de sobrecarga/trauma\n- Avaliar amplitude de movimento e sinais inflamatórios\n- Identificar necessidade de raio-X/USG/RM\n- Definir proteção articular e reabilitação','Encaminhar urgência se houver deformidade, déficit neurovascular, incapacidade de apoio, febre ou suspeita de fratura/agressão articular importante.','Orientar repouso relativo, analgesia, gelo/calor conforme caso e retorno para reavaliação funcional.','ortopedia, trauma, dor musculoesquelética',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
INSERT INTO `protocolos_clinicos` (`id`,`empresa_id`,`tema`,`titulo`,`categoria`,`objetivo`,`checklist`,`criterios`,`orientacoes`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7110,1,'oftalmologia','Triagem de baixa visual e olho vermelho','Triagem','Organizar avaliação inicial de queixas visuais frequentes, identificando sinais de gravidade e necessidade de investigação rápida.','- Avaliar acuidade visual e lateralidade da queixa\n- Investigar dor, secreção, fotofobia e trauma\n- Medir pressão intraocular quando indicado\n- Definir necessidade de exame complementar e retorno','Priorizar urgência se perda visual súbita, trauma ocular, dor intensa, fotofobia importante, secreção purulenta ou suspeita de glaucoma agudo.','Orientar evitar automedicação ocular, manter acompanhamento e retornar imediatamente se houver piora dos sintomas.','oftalmologia, baixa visual, olho vermelho, triagem',1,1,1,'2026-11-11 23:52:12','2026-11-11 23:52:12');
